<template><section class="work-panel"><div class="section-heading"><h2>{{ $ui('评分与评价') }}</h2><button class="secondary-button" :disabled="loading" @click="load(false)">{{ $ui('刷新') }}</button></div><p class="store-muted">{{ $ui('每个评价版本仅可回复一次。用户修改评价后，可再次回复；相同内容重复提交不会增加回复机会。') }}</p><p v-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><p v-if="loading" role="status">{{ $ui('正在读取…') }}</p><p v-if="!rows.length && !loading">{{ $ui('暂无评价。') }}</p><article v-for="review in rows" :key="review.id" class="store-review"><strong>{{ review.author_name || $ui('已注销账户') }}</strong><span>★ {{ review.score }} / 5</span><small> · {{ $ui('评价第{0}版',[review.revision]) }}</small><p>{{ review.body }}</p><div v-for="reply in review.replies" :key="reply.review_revision" class="publisher-review-response"><strong>{{ $ui('作者回复') }} · {{ $ui('评价第{0}版',[reply.review_revision]) }}</strong><p>{{ reply.body || $ui('此回复已删除。') }}</p></div><form v-if="review.can_reply" class="store-form" @submit.prevent="reply(review)"><label>{{ $ui('回复评价') }}<textarea v-model="drafts[review.id]" maxlength="2000" rows="3" required /></label><button class="primary-button" :disabled="Boolean(busy) || !drafts[review.id]?.trim()">{{ $ui('提交回复') }}</button></form><p v-else class="store-muted">{{ $ui('已回复当前版本，等待用户修改评价。') }}</p></article><button v-if="rows.length<total" class="secondary-button" :disabled="loading" @click="load(true)">{{ $ui('下一页') }}</button></section></template>
<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,reactive} from 'vue';
import {store,type StoreReview} from '@/api/store';
const props=defineProps<{itemId:string}>(),rows=ref<StoreReview[]>([]),total=ref(0),loading=ref(false),busy=ref(''),error=ref(''),drafts=reactive<Record<string,string>>({});let active=true;
async function load(more=false){if(loading.value)return;loading.value=true;error.value='';try{const page=await store.publisherReviews(props.itemId,more?rows.value.length:0);if(active){rows.value=more?[...rows.value,...page.data]:page.data;total.value=page.pagination.total;}}catch(e){if(active)error.value=e instanceof Error?e.message:'暂时无法读取评价';}finally{if(active)loading.value=false;}}
async function reply(review:StoreReview){if(busy.value)return;busy.value=review.id;error.value='';try{await store.replyReview(props.itemId,review,drafts[review.id]);if(active){drafts[review.id]='';await load(false);}}catch(e){if(active)error.value=e instanceof Error?e.message:'评价回复失败，请刷新后重试';}finally{if(active)busy.value='';}}
onMounted(()=>void load());onBeforeUnmount(()=>{active=false;});
</script>
